    "author": "",
    "description": "新华社北京11月18日电 题：生命至上 凡人微光——第四届“全国十佳救护员”速写 新华社记者董博婷、林凯 第四届“全国十佳救护员”名单18日发布，获评的十组救护人员和两位“特别致敬人选”共同书写着“生命至上”的动人故事。 专业有速度：流动防线护佑生命 2025年12月5日，疾驰的列车上，一名女性突发剧烈腹痛。听到广播响起寻医求助，云南省第一人民医院急诊内科护士长关万高立即响应。没有监护仪，没有检验设备，他凭借十余年急诊经验对症成功施救。…",
    "content": "新华社北京11月18日电 题：生命至上 凡人微光——第四届“全国十佳救护员”速写 新华社记者董博婷、林凯 第四届“全国十佳救护员”名单18日发布，获评的十组救护人员和两位“特别致敬人选”共同书写着“生命至上”的动人故事。 专业有速度：流动防线护佑生命 2025年12月5日，疾驰的列车上，一名女性突发剧烈腹痛。听到广播响起寻医求助，云南省第一人民医院急诊内科护士长关万高立即响应。没有监护仪，没有检验设备，他凭借十余年急诊经验对症成功施救。 背起倒地男子冒雨奔向医院、抢救被糖果卡喉的幼童、在车流中救下昏迷的独居老人………"
