    "description": "新华社香港11月18日电（谢妞）陪伴香港市民和旅客22年的灯光音乐汇演“幻彩咏香江”18日晚上演最后一场，其他光影项目将在明年陆续推出。 自2004年起，“幻彩咏香江”几乎每晚8时点亮香港夜空，以灯光、激光和音乐表演为市民和旅客带来难忘的回忆。2005年，这场视觉盛宴正式获列入《吉尼斯世界纪录大全》，成为全球最大型灯光音乐汇演。 表演期间，维多利亚港两岸超过40栋摩天大厦都会亮起灯光，参与表演的主要地标包括中环广场、香港会议展览中心、美…",
    "content": "新华社香港11月18日电（谢妞）陪伴香港市民和旅客22年的灯光音乐汇演“幻彩咏香江”18日晚上演最后一场，其他光影项目将在明年陆续推出。 自2004年起，“幻彩咏香江”几乎每晚8时点亮香港夜空，以灯光、激光和音乐表演为市民和旅客带来难忘的回忆。2005年，这场视觉盛宴正式获列入《吉尼斯世界纪录大全》，成为全球最大型灯光音乐汇演。 表演期间，维多利亚港两岸超过40栋摩天大厦都会亮起灯光，参与表演的主要地标包括中环广场、香港会议展览中心、美国银行中心、汇丰总行大厦以及国际金融中心等。 当天，维多利亚港两岸聚集了大批市民…"
