    "description": "项目地址：Myco 包含 Mac 和 Windows 客户端，以及 iOS 移动端。 背景 项目背景是我想薅 A/羊毛，做一个能够让我远程调用 claude.ai 上的 agent，薅 claude 羊毛的客户端，结果做着做着发现，这么久了，市面上很多客户端体验还很落后，于是想分享给大家试试。 当然如果你想无风险使用 claude，也推荐你用 myco。但你只想管理自己不同订阅的 agent，放到一个地方，我相信这肯定是全网你能找到的体…",
    "content": "项目地址： Myco 包含 Mac 和 Windows 客户端，以及 iOS 移动端。 背景 项目背景是我想薅 A/羊毛，做一个能够让我远程调用 claude.ai 上的 agent，薅 claude 羊毛的客户端，结果做着做着发现，这么久了，市面上很多客户端体验还很落后，于是想分享给大家试试。 当然如果你想无风险使用 claude，也推荐你用 myco。但你只想管理自己不同订阅的 agent，放到一个地方，我相信这肯定是全网你能找到的体验最好的 APP 了（有点自吹自擂了，请轻喷，但真是矮子里面拔高个）。 特性 …"
