    "content": "新华社多哈11月18日电 第21届亚运会竞赛协调会18日在卡塔尔多哈召开，会议就多哈亚运会赛期调整方案向参会各方征集最终意见。 根据提案，原定于2030年举办的多哈亚运会拟延后至2031年举行，从而进一步对接夏季奥运会备战周期。 本次会议共有45个亚洲单项体育联合会代表及亚奥理事会电竞协调小组成员参会。亚奥理事会主席焦安亲王在致辞中表示，本次会议旨在听取各方对将多哈亚运会由2030年改至2031年举办的最终意见。这一调整方案将有助于亚运会的举办周期与奥运会周期更加紧密地衔接，从而为亚运会发挥更重要的作用创造更多机会…"
