    "title": "斐济宣布因持续干旱进入灾难状态",
    "link": "http://www.news.cn/20261118/ff5641fc38854de3be26413ab38b13e5/c.html",
    "pub_date": "2026-11-18 22:16:29",
    "author": "",
    "description": "新华社苏瓦11月18日电（记者白涌泉 郭鑫惠）因遭遇罕见持续干旱，南太平洋岛国斐济18日正式宣布全国进入灾难状态，全力应对严峻缺水危机。 斐济总理兰布卡表示，灾难状态启动后，政府将有权统一调配应急队伍、救灾物资及各类公共资源。目前，政府已专项划拨2000万斐济元（约合5800万元人民币）救灾资金，用于应急供水保障、受灾社区帮扶、农业养殖救济及干旱衍生灾害处置等工作。 斐济属热带海洋性气候，常年降水充沛。今年以来，强厄尔尼诺现象打破当地水…",
    "content": "新华社苏瓦11月18日电（记者白涌泉 郭鑫惠）因遭遇罕见持续干旱，南太平洋岛国斐济18日正式宣布全国进入灾难状态，全力应对严峻缺水危机。 斐济总理兰布卡表示，灾难状态启动后，政府将有权统一调配应急队伍、救灾物资及各类公共资源。目前，政府已专项划拨2000万斐济元（约合5800万元人民币）救灾资金，用于应急供水保障、受灾社区帮扶、农业养殖救济及干旱衍生灾害处置等工作。 斐济属热带海洋性气候，常年降水充沛。今年以来，强厄尔尼诺现象打破当地水文常态，引发罕见持续干旱，让这个水资源丰裕的岛国陷入严重缺水危机。斐济官方预警显…"
