    "description": "中新社深圳11月18日电 (记者 尹倩芸)《2026年亚太经合组织工商领导人峰会深圳倡议》18日对外发布。倡议呼吁深化开放型区域经济、以技术创新驱动包容增长、畅通区域一体化动脉、携手实现共同繁荣。这是APEC工商领导人峰会创办30年来首次以倡议形式发布成果文件。",
    "content": "中新社深圳11月18日电 (记者 尹倩芸)《2026年亚太经合组织工商领导人峰会深圳倡议》18日对外发布。倡议呼吁深化开放型区域经济、以技术创新驱动包容增长、畅通区域一体化动脉、携手实现共同繁荣。这是APEC工商领导人峰会创办30年来首次以倡议形式发布成果文件。"
