    "pub_date": "2026-11-18 21:47:08",
    "author": "",
    "description": "新华社土耳其安塔利亚11月18日电（记者张晓茹 王腾飞）航运业减排是全球绿色转型的难点之一。中国科学家在《联合国气候变化框架公约》第三十一次缔约方大会（COP31）期间提出，以船载微藻协同利用船舶发动机尾气中的二氧化碳和生活污水，推动船舶由碳排放源向移动碳汇转变。 “凝聚国际共识，携手推进海洋负排放”专题边会日前在COP31蓝区海洋角举行，由海洋负排放国际大科学计划和厦门大学共同主办，美国伍兹霍尔海洋研究所及中国科协联合国咨商海洋生态可…",
    "content": "新华社土耳其安塔利亚11月18日电（记者张晓茹 王腾飞）航运业减排是全球绿色转型的难点之一。中国科学家在《联合国气候变化框架公约》第三十一次缔约方大会（COP31）期间提出，以船载微藻协同利用船舶发动机尾气中的二氧化碳和生活污水，推动船舶由碳排放源向移动碳汇转变。 “凝聚国际共识，携手推进海洋负排放”专题边会日前在COP31蓝区海洋角举行，由海洋负排放国际大科学计划和厦门大学共同主办，美国伍兹霍尔海洋研究所及中国科协联合国咨商海洋生态可持续发展专业委员会等协办。中国科学院院士、海洋负排放国际大科学计划首席科学家焦念…"
