    "description": "新华社北京11月18日电（记者刘祯）记者11月18日获悉，中国科学院电工研究所自研的10台分布式电涵道推进电机系统近日完成实飞验证，系统总功率2兆瓦，为我国自主研制的首款电动商用飞机CE-25A提供全部动力。 CE-25A是中国商飞研制的首款10吨级电动商用飞机。不同于传统燃油客机，纯电动航空对动力系统功重比提出极高要求。 为此，中国科学院电工研究所团队确立了基于涵道流场强迫风冷的技术路线，创新采用电机—变流器深度融合一体化构型，突破多…",
    "content": "新华社北京11月18日电（记者刘祯）记者11月18日获悉，中国科学院电工研究所自研的10台分布式电涵道推进电机系统近日完成实飞验证，系统总功率2兆瓦，为我国自主研制的首款电动商用飞机CE-25A提供全部动力。 CE-25A是中国商飞研制的首款10吨级电动商用飞机。不同于传统燃油客机，纯电动航空对动力系统功重比提出极高要求。 为此，中国科学院电工研究所团队确立了基于涵道流场强迫风冷的技术路线，创新采用电机—变流器深度融合一体化构型，突破多项关键技术，大幅提升飞行安全性，有效解决了液冷方案辅件繁杂、重量偏大带来的适航取…"
