    "content": "有多少江浙沪的朋友跟我一样，今早是被冻醒的？ 昨天下了一天雨，今天开启了断崖式降温。 但是没想到，在我筹备羽绒服的项目时候，搜索到央视财经曝光的一条新闻，更是让人从头到脚透心凉。 几万件羽绒服竟然全是假货，绒子含量几乎为零，可这些衣服的吊牌、水洗标、羽绒充气标、执行标准、产品等级一样不少，甚至还配了检验检测报告。 原因无他，大多数人买羽绒服，第一眼看款式，第二眼摸厚薄，第三眼再看价格。 结果穿上一阵才发现：看着挺厚，保暖一般；标签写得很满，真到较真的时候，说不清绒从哪来、批次怎么查、检测报告对应哪一件。 而且今年羽…"
