    "content": "新华社深圳11月18日电 韩国总统李在明18日在深圳出席亚太经合组织工商领导人峰会时表示，亚太经合组织是21个经济体的合作舞台。面对日益增高的贸易壁垒，亚太各经济体迈向开放的步伐不能停歇。 李在明在峰会上致辞说，以人工智能为代表的技术革命、气候变化和人口结构调整等正在彻底改变产业格局，各方需要寻找新的增长动力。当下最紧迫的任务，是扩大亚太经合组织区域内的贸易与投资，拓展新的增长机会。 李在明说，亚太各方应当充分利用人工智能革命带来的红利，让创新惠及所有人。为了打造稳定的产业基础与供应链，各方必须深化合作。 李在明表…"
