    "description": "36氪获悉，康迪科技披露2026年前三季度财务报告。报告期内，公司实现营业收入8210万美元，同比增长38.5%，并实现扭亏为盈，净利润560万美元。其中，非公路电动车及相关零部件业务实现收入7400万美元，同比增长33.5%；能源换电装备业务于第三季度正式产生收入，新业务商业化进入兑现阶段。",
