    "content": "今晚，南海之滨灯火璀璨，鹏城深圳秋意盎然。在亚太经合组织第三十三次领导人非正式会议即将召开之际，我谨代表中国政府和中国人民，对各位嘉宾的到来表示热烈欢迎。 我曾讲过，看千年的中国去西安，看五百年的中国去北京，看一百年的中国去上海。今天，我想对大家说，看五十年的中国就来深圳。深圳是一个有大故事的地方。1978年，我第一次到深圳，看到的还是一个小渔村。弹指间40多年过去了，如今这里高楼林立、车水马龙，变化之大可谓沧海桑田。开放是深圳与生俱来的基因。从边陲小镇到国际化大都市，从引进外资和技术到积极参与制定国际规则，今天的…"
