    "content": "新华社重庆11月18日电（记者赵佳乐）18日，在重庆举行的2026现代服务业高质量发展大会上，“中国品牌全球行·匠心服务计划”正式启动。此计划聚焦现代服务业企业出海需求，旨在助力中国服务品牌拓展国际市场、提升全球影响力。 据介绍，“中国品牌全球行”是新华社推出的重点项目，依托新华社全球布局、全球采集、全球传播、全球到达优势，面向全球展示中国城市创新活力和中国企业核心竞争力。此次启动的“匠心服务计划”将围绕服务业企业品牌提升，打造日常传播、站点活动、IP策划、资源对接、品销合一五大服务体系，助力中国服务品牌全球化发展…"
